ScrollView {
    VStack(alignment: .leading, spacing: MonarchTokens.Space.space4) {
        HStack {
            VStack(alignment: .leading) {
                Text({{title}}).monarchTextStyle(.title)
                Text({{description}}).monarchTextStyle(.body)
            }
            Spacer(minLength: 0)
            Button {} label: { Text("Support").monarchTextStyle(.label).foregroundStyle(theme.colors.textLink) }
        }
        MonarchBanner("Degraded performance", tone: .warning)
        HStack(alignment: .top, spacing: MonarchTokens.Space.space2) {
            stat("Uptime · 30d", "{{overallUptimePercent|raw}}%")
            stat("Services", "{{kpis.services|raw}}")
            stat("Active incidents", "{{kpis.activeIncidents|raw}}", danger: true)
        }
        eyebrow("Active incidents")
        incident(theme.colors.warningSolid) {
            VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
                HStack(alignment: .top) {
                    Text({{activeIncident.title}}).monarchTextStyle(.bodyStrong)
                    Spacer(minLength: 0)
                    MonarchStatusBadge(MonarchStatusDefinition("Investigating", tone: .warning), size: .sm).fixedSize()
                }
                Text("{{activeIncident.component|raw}} · \(stamp({{activeIncident.openedAt|date}}))").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
            MonarchIncidentTimeline([
                MonarchIncidentUpdate(id: "1", stage: {{activeIncident.updates.0.stage|case}}, body: {{activeIncident.updates.0.body}}, time: {{activeIncident.updates.0.time|date}}, isAutomated: {{activeIncident.updates.0.automated}}),
                MonarchIncidentUpdate(id: "2", stage: {{activeIncident.updates.1.stage|case}}, body: {{activeIncident.updates.1.body}}, time: {{activeIncident.updates.1.time|date}}, isAutomated: {{activeIncident.updates.1.automated}}),
                ])
            }
        }
        eyebrow("Services")
        eyebrow({{group}})
        card {
          VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
            VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
                HStack {
                    Text({{services.0.name}}).monarchTextStyle(.bodyStrong)
                    Text("{{services.0.responseTimeMs|raw}} ms").monarchTextStyle(.caption)
                    Spacer(minLength: 0)
                    MonarchStatusBadge({{services.0.state}}, size: .sm)
                }
                MonarchUptimeBar(segments: days([{{services.0.history.0.day}}: {{services.0.history.0.state|case}}]), overallUptime: {{services.0.uptimePercent|double}}, startLabel: "30 days ago", endLabel: "Today", size: .sm)
            }
            Divider()
            VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
                HStack {
                    Text({{services.1.name}}).monarchTextStyle(.bodyStrong)
                    Text("{{services.1.responseTimeMs|raw}} ms").monarchTextStyle(.caption)
                    Spacer(minLength: 0)
                    MonarchStatusBadge({{services.1.state}}, size: .sm)
                }
                MonarchUptimeBar(segments: days([{{services.1.history.0.day}}: {{services.1.history.0.state|case}}, {{services.1.history.1.day}}: {{services.1.history.1.state|case}}]), overallUptime: {{services.1.uptimePercent|double}}, startLabel: "30 days ago", endLabel: "Today", size: .sm)
            }
            Divider()
            VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
                HStack {
                    Text({{services.2.name}}).monarchTextStyle(.bodyStrong)
                    Text("{{services.2.responseTimeMs|raw}} ms").monarchTextStyle(.caption)
                    Spacer(minLength: 0)
                    MonarchStatusBadge({{services.2.state}}, size: .sm)
                }
                MonarchUptimeBar(segments: days([:]), overallUptime: {{services.2.uptimePercent|double}}, startLabel: "30 days ago", endLabel: "Today", size: .sm)
            }
          }
        }
        card {
          VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
            VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
                HStack {
                    VStack(alignment: .leading) {
                        Text({{services.3.name}}).monarchTextStyle(.bodyStrong)
                        Text({{services.3.description}}).monarchTextStyle(.caption)
                    }
                    Spacer(minLength: 0)
                    MonarchStatusBadge({{services.3.state}}, size: .sm)
                }
                MonarchUptimeBar(segments: days([{{services.3.history.0.day}}: {{services.3.history.0.state|case}}]), overallUptime: {{services.3.uptimePercent|double}}, startLabel: "30 days ago", endLabel: "Today", size: .sm)
            }
          }
        }
        MonarchFlowLayout(spacing: MonarchTokens.Space.space3) {
            key("Operational", theme.colors.successSolid)
            key("Degraded", theme.colors.warningSolid)
            key("Down", theme.colors.dangerSolid)
            key("Maintenance", theme.colors.infoSolid)
            key("No data", theme.colors.bgEmphasis)
        }
        eyebrow("Past incidents")
        incident(theme.colors.dangerSolid) {
            VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
                HStack(alignment: .top) {
                    Text({{pastIncident.title}}).monarchTextStyle(.bodyStrong)
                    Spacer(minLength: 0)
                    MonarchStatusBadge(MonarchStatusDefinition("Resolved", tone: .success), size: .sm).fixedSize()
                }
                Text("{{pastIncident.component|raw}} · \(stamp({{pastIncident.openedAt|date}})) · lasted \({{pastIncident.durationSeconds}} / 60)m").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
            MonarchIncidentTimeline([
                MonarchIncidentUpdate(id: "1", stage: {{pastIncident.updates.0.stage|case}}, body: {{pastIncident.updates.0.body}}, time: {{pastIncident.updates.0.time|date}}, isAutomated: {{pastIncident.updates.0.automated}}),
                MonarchIncidentUpdate(id: "2", stage: {{pastIncident.updates.1.stage|case}}, body: {{pastIncident.updates.1.body}}, time: {{pastIncident.updates.1.time|date}}, isAutomated: {{pastIncident.updates.1.automated}}),
                ])
            }
        }
        Divider()
        HStack(alignment: .bottom, spacing: MonarchTokens.Space.space2) {
            MonarchTextField("Subscribe to updates", text: $email, prompt: "you@example.com", helper: "Get an email when an incident is opened, updated or resolved.", isRequired: true).monarchHelperAbove()
            MonarchButton("Subscribe", variant: .secondary) {}
        }
        Text("Updated \(Int({{now|date}}.timeIntervalSince({{updatedAt|date}})) / 60) minute ago").monarchTextStyle(.caption)
    }
    .padding()
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var email = ""
private func card<Content: View>(@ViewBuilder _ content: () -> Content) -> some View {
    content()
        .padding(MonarchTokens.Space.space3)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(theme.colors.bgSurface, in: RoundedRectangle(cornerRadius: MonarchTokens.Radius.lg, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: MonarchTokens.Radius.lg, style: .continuous).strokeBorder(theme.colors.borderSubtle, lineWidth: MonarchTokens.Space.px))
}
private func eyebrow(_ title: String) -> some View {
    Text(title).monarchTextStyle(.label).textCase(.uppercase).tracking(0.6).foregroundStyle(theme.colors.textMuted)
}
private func stat(_ title: String, _ value: String, danger: Bool = false) -> some View {
    VStack(alignment: .leading, spacing: MonarchTokens.Space.space1) {
        Text(title).monarchTextStyle(.caption).textCase(.uppercase).lineLimit(2).foregroundStyle(theme.colors.textMuted)
        Text(value).monarchTextStyle(.title).lineLimit(1).minimumScaleFactor(0.6).foregroundStyle(danger ? theme.colors.dangerStrong : theme.colors.textDefault)
    }
    .frame(maxWidth: .infinity, alignment: .leading)
    .padding(MonarchTokens.Space.space3)
    .background(theme.colors.bgSurface, in: RoundedRectangle(cornerRadius: MonarchTokens.Radius.lg, style: .continuous))
    .overlay(RoundedRectangle(cornerRadius: MonarchTokens.Radius.lg, style: .continuous).strokeBorder(theme.colors.borderSubtle, lineWidth: MonarchTokens.Space.px))
}
private func incident<Content: View>(_ color: Color, @ViewBuilder _ content: () -> Content) -> some View {
    card(content)
        .overlay(alignment: .leading) { Rectangle().fill(color).frame(width: MonarchTokens.Space.space0_5) }
        .clipShape(RoundedRectangle(cornerRadius: MonarchTokens.Radius.lg, style: .continuous))
}
private func key(_ title: String, _ color: Color) -> some View {
    HStack(spacing: MonarchTokens.Space.space1) {
        RoundedRectangle(cornerRadius: MonarchTokens.Space.space0_5, style: .continuous).fill(color).frame(width: MonarchTokens.Space.space2_5, height: MonarchTokens.Space.space2_5)
        Text(title).monarchTextStyle(.caption)
    }
}
private func stamp(_ date: Date) -> String {
    let formatter = DateFormatter()
    formatter.locale = Locale(identifier: "en-US")
    formatter.timeZone = TimeZone(identifier: "UTC")
    formatter.dateFormat = "MMM d, HH:mm 'UTC'"
    return formatter.string(from: date)
}
private func days(_ marks: [Int: MonarchUptimeBarStatus]) -> [MonarchUptimeBarSegment] {
    (1...30).map { MonarchUptimeBarSegment(id: "\($0)", label: "Day \($0)", status: marks[$0] ?? .operational) }
}

