ScrollView {
    VStack(alignment: .leading, spacing: MonarchTokens.Space.space4) {
        HStack {
            VStack(alignment: .leading) {
                Text("Example status").monarchTextStyle(.title)
                Text("Live health of our services.").monarchTextStyle(.body)
            }
            Spacer(minLength: 0)
            Button {} label: { Text("Support").monarchTextStyle(.label).foregroundStyle(theme.colors.textLink) }
        }
        MonarchBanner("Degraded performance", tone: .warning)
        HStack(alignment: .top, spacing: MonarchTokens.Space.space2) {
            stat("Uptime · 30d", "99.89%")
            stat("Services", "4")
            stat("Active incidents", "1", danger: true)
        }
        eyebrow("Active incidents")
        incident(theme.colors.warningSolid) {
            VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
                HStack(alignment: .top) {
                    Text("Slow page loads in the web app").monarchTextStyle(.bodyStrong)
                    Spacer(minLength: 0)
                    MonarchStatusBadge(MonarchStatusDefinition("Investigating", tone: .warning), size: .sm).fixedSize()
                }
                Text("Web app · \(stamp(Date(timeIntervalSince1970: 1_774_860_000)))").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
            MonarchIncidentTimeline([
                MonarchIncidentUpdate(id: "1", stage: .investigating, body: "Response times are higher than usual. We are looking into it.", time: Date(timeIntervalSince1970: 1_774_860_300), isAutomated: true),
                MonarchIncidentUpdate(id: "2", stage: .identified, body: "A slow database query is the cause. A fix is being deployed.", time: Date(timeIntervalSince1970: 1_774_861_800), isAutomated: false),
                ])
            }
        }
        eyebrow("Services")
        eyebrow("Platform")
        card {
          VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
            VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
                HStack {
                    Text("API").monarchTextStyle(.bodyStrong)
                    Text("128 ms").monarchTextStyle(.caption)
                    Spacer(minLength: 0)
                    MonarchStatusBadge("operational", size: .sm)
                }
                MonarchUptimeBar(segments: days([12: .degraded]), overallUptime: 99.97, startLabel: "30 days ago", endLabel: "Today", size: .sm)
            }
            Divider()
            VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
                HStack {
                    Text("Web app").monarchTextStyle(.bodyStrong)
                    Text("410 ms").monarchTextStyle(.caption)
                    Spacer(minLength: 0)
                    MonarchStatusBadge("degraded", size: .sm)
                }
                MonarchUptimeBar(segments: days([5: .down, 30: .degraded]), overallUptime: 99.62, startLabel: "30 days ago", endLabel: "Today", size: .sm)
