            Divider()
            VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
                HStack {
                    Text("Sign-in").monarchTextStyle(.bodyStrong)
                    Text("96 ms").monarchTextStyle(.caption)
                    Spacer(minLength: 0)
                    MonarchStatusBadge("operational", size: .sm)
