          }
        }
        card {
          VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
            VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
                HStack {
                    VStack(alignment: .leading) {
                        Text("Email delivery").monarchTextStyle(.bodyStrong)
                        Text("Outbound notifications").monarchTextStyle(.caption)
                    }
                    Spacer(minLength: 0)
                    MonarchStatusBadge("operational", size: .sm)
                }
