                HStack(alignment: .top) {
                    Text("Sign-in errors").monarchTextStyle(.bodyStrong)
                    Spacer(minLength: 0)
                    MonarchStatusBadge(MonarchStatusDefinition("Resolved", tone: .success), size: .sm).fixedSize()
                }
                Text("Sign-in · \(stamp(Date(timeIntervalSince1970: 1_772_719_320))) · lasted \(2820 / 60)m").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
            MonarchIncidentTimeline([
                MonarchIncidentUpdate(id: "1", stage: .investigating, body: "Some people cannot sign in.", time: Date(timeIntervalSince1970: 1_772_719_500), isAutomated: false),
                MonarchIncidentUpdate(id: "2", stage: .resolved, body: "Sign-in is working again for everyone.", time: Date(timeIntervalSince1970: 1_772_722_140), isAutomated: false),
                ])
